/*
 * Describes a PCI vendor and locates its devices in pci_devices[].
 * device_offset + device_count define the contiguous slice for this vendor.
 */
typedef struct {
    uint16_t    vendor;
    uint32_t    device_offset;  /* Index of first device in pci_devices[] */
    uint32_t    device_count;   /* Number of consecutive devices          */
    const char* name;
} pci_vendor_t;

