static const unsigned int pci_vendor_count = sizeof(pci_vendors) / sizeof(pci_vendors[0]);
static const unsigned int pci_class_count = sizeof(pci_classes) / sizeof(pci_classes[0]);

/*
 * Returns the name of the PCI class/subclass.
 * If the specific subclass is unknown, it returns the base class name.
 */
static inline const char* get_pci_class_name(uint8_t base_id, uint8_t sub_id) {
    const char* fallback = "Unknown Class";
    for (unsigned int i = 0; i < pci_class_count; i++) {
        if (pci_classes[i].base_class == base_id) {
            if (pci_classes[i].sub_class == sub_id) return pci_classes[i].name;
            if (pci_classes[i].sub_class == 0xff) fallback = pci_classes[i].name;
        }
    }
    return fallback;
}

/*
 * Binary search for a vendor entry by id.
 * Returns a pointer into pci_vendors[], or NULL if not found.
 */
static inline const pci_vendor_t* pci_find_vendor(uint32_t vendor_id) {
    int left  = 0;
    int right = (int)pci_vendor_count - 1;
    while (left <= right) {
        int mid      = left + (right - left) / 2; /* avoids overflow vs (l+r)/2 */
        uint16_t v   = pci_vendors[mid].vendor;
        if      (v == vendor_id) return &pci_vendors[mid];
        else if (v <  vendor_id) left  = mid + 1;
        else                     right = mid - 1;
    }
    return 0;
}

/* Returns the vendor name string, or "Unknown Vendor" if not found. */
static inline const char* get_pci_vendor_name(uint32_t vendor_id) {
    const pci_vendor_t* v = pci_find_vendor(vendor_id);
    return v ? v->name : "Unknown Vendor";
}

/*
 * Two-stage lookup:
 *   1. Binary search pci_vendors[] for the vendor.
 *   2. Binary search that vendor's slice of pci_devices[] for the device.
 * Returns the device name string, or "Unknown Device" if either lookup fails.
 */
static inline const char*get_pci_device_name(uint32_t vendor_id, uint32_t device_id) {
    const pci_vendor_t* v = pci_find_vendor(vendor_id);
    if (!v) return "Unknown Device";

    int left  = 0;
    int right = (int)v->device_count - 1;
    while (left <= right) {
        int mid              = left + (right - left) / 2;
        const pci_device_t* d = &pci_devices[v->device_offset + mid];
        if      (d->device == device_id) return d->name;
        else if (d->device <  device_id) left  = mid + 1;
        else                             right = mid - 1;
    }
    return "Unknown Device";
}

